<script setup>defineProps({title:String})</script><template><section class="completion-page"><h1>{{title}}</h1><slot /></section></template><style>.completion-page{background:#f7f5f0;color:#142b4f;padding:24px max(20px,calc((100vw - 1100px)/2));font-family:inherit;overflow-wrap:anywhere}.completion-page nav{display:flex;gap:18px;flex-wrap:wrap;margin-bottom:32px}.completion-page h1{font-size:32px;margin-bottom:24px}.completion-page h2{font-size:20px;margin:16px 0}.completion-page section,.completion-card{background:white;border:1px solid #e4ded3;border-radius:18px;padding:20px;margin:16px 0}.completion-page label{display:block;margin:12px 0}.completion-page input,.completion-page textarea,.completion-page select,.completion-input{max-width:100%;padding:10px;border:1px solid #d6dce3;border-radius:8px;background:white}.completion-page textarea{width:100%;min-height:100px}.completion-page button,.completion-button{border:1px solid #142b4f;border-radius:22px;padding:10px 18px;margin:6px;background:#142b4f;color:white;font-size:13px}.completion-page button:disabled{opacity:.5}.completion-page :focus-visible{outline:3px solid #b49362;outline-offset:3px}.completion-page [role=alert]{color:#a73333;margin:12px 0}.completion-page [role=status]{margin:12px 0}</style>
